document.addEventListener("keydown", e => {
  if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA" || e.target.tagName === "SELECT" || e.target.isContentEditable)) return;
  if (window.__subject && window.__subject !== "en") return;
  if (e.key === "Escape") {
    closePackPopover();
    if (typeof closeFilterPopover === "function") closeFilterPopover();
    closeFsrsModal();
    if (window.Core && Core.closeGlobalOptions) Core.closeGlobalOptions();
    if (window.Stats && Stats.close) Stats.close();
    if (window.DueBell && DueBell.close) DueBell.close();
    if (typeof closeSubjectNav === "function") closeSubjectNav();
    return;
  }
  if (window.hasOpenOverlay && window.hasOpenOverlay()) return;
  if (e.repeat && (e.code === "Space" || ["1", "2", "3", "4", "z", "Z"].includes(e.key))) {
    e.preventDefault();
    return;
  }
  if (e.key.toLowerCase() === "f" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    toggleZenFullscreen();
    return;
  }
  if (e.key.toLowerCase() === "r" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    if (activeWord) speakWord(activeWord, null, false);
    return;
  }
  if (e.key.toLowerCase() === "v" && !e.ctrlKey && !e.metaKey && !e.altKey) {
    e.preventDefault();
    cycleVoiceMode();
    return;
  }
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
    e.preventDefault();
    undoLastRating();
    return;
  }

  const flat = window._flatFilteredCoreWords || [];
  if (flat.length === 0) return;

  if (e.code === "Space") {
    e.preventDefault();
    if (viewMode === "stage") flipStageCard();
    else if (activeWord) toggleCard(activeWord);
  } else if (["1", "2", "3", "4"].includes(e.key)) {
    e.preventDefault();
    if (viewMode === "stage" && !isStageFlipped) {
      flipStageCard();
      return;
    }
    if (activeWord && flat.some(x => x.w === activeWord)) {
      rateWord(activeWord, parseInt(e.key, 10), null);
    }
  } else if (e.key === "ArrowRight" || e.key === "ArrowDown" || e.key === "j" || e.key === "l") {
    e.preventDefault();
    if (viewMode === "stage") stepStageCard(1);
    else stepListCard(1);
  } else if (e.key === "ArrowLeft" || e.key === "ArrowUp" || e.key === "k" || e.key === "h") {
    e.preventDefault();
    if (viewMode === "stage") stepStageCard(-1);
    else stepListCard(-1);
  }
});

